// TWO-END: find a pair summing to target in a SORTED array
static int[] pairSum(int[] a, int target) {
    int left = 0, right = a.length - 1;
    while (left < right) {
        int sum = a[left] + a[right];
        if (sum == target) return new int[]{a[left], a[right]};
        if (sum < target) left++;     // need bigger -> move left right
        else right--;                 // need smaller -> move right left
    }
    return new int[]{-1, -1};
}

// SAME-DIRECTION: remove duplicates from a SORTED array in place
static int dedup(int[] a) {
    int slow = 0;
    for (int fast = 1; fast < a.length; fast++)
        if (a[fast] != a[slow]) a[++slow] = a[fast];
    return slow + 1;                  // new logical length
}
