public class DuplicateRemover {
    public int removeDuplicates(int[] nums) {
        if (nums == null || nums.length == 0) return 0;
        int slow = 0;                          // last unique position
        for (int fast = 1; fast < nums.length; fast++) {
            if (nums[fast] != nums[slow]) {    // found a new unique value
                slow++;
                nums[slow] = nums[fast];       // write to next unique slot
            }
        }
        return slow + 1;                       // new logical length
    }

    public static void main(String[] args) {
        int[] nums = {1, 1, 2, 2, 2, 3, 4, 4};
        int len = new DuplicateRemover().removeDuplicates(nums);
        System.out.println("New length: " + len);   // 4 -> [1, 2, 3, 4, ...]
    }
}
