public class PairSumFinder {
    public int[] findPairWithSum(int[] nums, int target) {
        if (nums == null || nums.length < 2) return new int[]{-1, -1};
        int left = 0, right = nums.length - 1;

        while (left < right) {
            int sum = nums[left] + nums[right];
            if (sum == target) return new int[]{nums[left], nums[right]};
            else if (sum < target) left++;     // need larger sum
            else right--;                       // need smaller sum
        }
        return new int[]{-1, -1};
    }

    public static void main(String[] args) {
        int[] nums = {1, 3, 5, 7, 9, 11};
        int[] r = new PairSumFinder().findPairWithSum(nums, 14);
        System.out.println("Pair: [" + r[0] + ", " + r[1] + "]");  // [3, 11]
    }
}
